#!/usr/bin/env node
/**
 * Device-side OFFLINE OpenSSL/TLS evidence probe (failure 2 acceptance).
 *
 * Runs under the embedded Bionic node with airplane mode ON. Proves:
 *  1. OpenSSL initialized WITHOUT touching /data/data/com.termux (env audit);
 *  2. OPENSSL_CONF is set, inside the app runtime, and readable;
 *  3. a full TLS 1.2+ handshake with certificate VERIFICATION succeeds on
 *     loopback using the bundled OpenSSL — offline, no network, no Termux.
 *
 * The server certificate/key pair is generated by the CI runner (openssl
 * CLI) and pushed to the device; the client pins it via `ca`, so
 * `authorized === true` proves the whole verify path works on-device.
 * Exit 0 + "TLS-OFFLINE-OK ..." = pass. Anything else = fail (loudly).
 */
'use strict';
const assert = require('assert');
const fs = require('fs');
const tls = require('tls');

const [, , certPath, keyPath] = process.argv;
assert(certPath && keyPath, 'usage: verify-tls-offline-probe.cjs <cert.pem> <key.pem>');

const conf = process.env.OPENSSL_CONF || '';
const modules = process.env.OPENSSL_MODULES || '';

// --- 1. environment audit: everything inside the runtime, nothing Termux ---
assert(conf.length > 0, 'OPENSSL_CONF is not set — OpenSSL would read the compiled-in Termux path');
assert(!conf.includes('com.termux'), 'OPENSSL_CONF leaks a Termux path: ' + conf);
assert(!modules.includes('com.termux'), 'OPENSSL_MODULES leaks a Termux path: ' + modules);
fs.accessSync(conf, fs.constants.R_OK); // throws EACCES exactly like the device failure 2

const leaks = Object.entries(process.env)
  .filter(([k, v]) => typeof v === 'string' && v.includes('com.termux'))
  .map(([k]) => k);
assert.strictEqual(leaks.length, 0, 'ENV LEAKS TERMUX PATHS: ' + leaks.join(','));

// --- 2. node-level TLS sanity (root store present, verification default-on) --
assert(tls.rootCertificates.length > 100,
  'node root store unexpectedly small: ' + tls.rootCertificates.length);

// --- 3. real handshake on loopback with verification REQUIRED ---------------
const cert = fs.readFileSync(certPath);
const key = fs.readFileSync(keyPath);
const server = tls.createServer({ cert, key }, () => {});
server.listen(0, '127.0.0.1', () => {
  const port = server.address().port;
  const socket = tls.connect({
    port,
    host: '127.0.0.1',
    ca: cert,               // pinned CA -> authorized must be true
    rejectUnauthorized: true, // verification explicitly REQUIRED (never off)
    servername: 'localhost',
  }, () => {
    const evidence = {
      node: process.version,
      platform: process.platform,
      arch: process.arch,
      opensslConf: conf,
      opensslModules: modules || null,
      protocol: socket.getProtocol(),
      cipher: socket.getCipher().name,
      authorized: socket.authorized,
      rootCertificates: tls.rootCertificates.length,
    };
    assert.strictEqual(socket.authorized, true, 'TLS verification failed: ' + socket.authorizationError);
    console.log('TLS-OFFLINE-OK ' + JSON.stringify(evidence));
    socket.end();
    server.close(() => process.exit(0));
  });
  socket.on('error', (e) => {
    console.error('TLS-OFFLINE-FAIL ' + e.message);
    server.close();
    process.exit(1);
  });
});
server.on('error', (e) => {
  console.error('TLS-OFFLINE-FAIL server: ' + e.message);
  process.exit(1);
});
